"use strict";
GUIDE_DATA_EN.sections.push({"id":"g128","part":13,"title":"Resolve Issues","blocks":[{"level":1,"text":"Risk"},{"level":2,"text":"Potential future events that may or may not occur"},{"level":1,"text":"The issue management process involves several steps"},{"level":2,"text":"Identify the issue and record it in an issue log"},{"level":2,"text":"Analyze the issue, determine the cause and impact, and prioritize"},{"level":2,"text":"Resolve the issue by deciding which actions to take and implementing them"},{"level":2,"text":"Monitor the issue to ensure it is resolved and closed in the issue log"},{"level":1,"text":"To effectively manage issues, it is important to establish an issue tracking process and escalation points"},{"level":1,"text":"Analyzing issues involves conducting a root cause analysis to determine why the issue occurs"},{"level":1,"text":"Various tools can be used for analysis, including scatter diagrams, run charts, pareto charts, five-why analysis, and fishbone diagrams"},{"level":1,"text":"Issue analysis process is used to determine the relative priority of an issue"},{"level":2,"text":"It is recommended to reevaluate issues as the severity and criteria may differ"},{"level":2,"text":"Factors such as issue severity, urgency, impact on the project and organization, issue escalation, and issue prioritization are considered in the analysis"},{"level":1,"text":"Severity measures the extent of the issue's effect, while urgency determines how quickly it needs to be addressed"},{"level":1,"text":"After resolving issues, it is important to monitor them to ensure they stay resolved and to identify new issues"},{"level":1,"text":"Control Chart"},{"level":2,"text":"Statistical chart used to track the variation in a process"},{"level":2,"text":"They include a center line, upper control limit, and lower control limit to identify when a process is out of control"},{"level":1,"text":"Effective issue management requires a culture of transparency, proactive reporting of issues, and clear communication channels"}]},{"id":"g129","part":13,"title":"Issue Management Overview","blocks":[{"level":1,"text":"Risk"},{"level":2,"text":"A potential future event that may or may not occur"},{"level":2,"text":"Risks can be positive or negative"},{"level":1,"text":"Not every issue is identified in the risk management plan"},{"level":1,"text":"Unknown risks will turn into current events (issues)"},{"level":1,"text":"Issue management processes will vary by organization but generally cover four broad categories"},{"level":2,"text":"Identify and record issue"},{"level":2,"text":"Analyze the issue"},{"level":2,"text":"Resolve the issue"},{"level":2,"text":"Monitor and close the issue"}]},{"id":"g130","part":13,"title":"Identify the Issue","blocks":[{"level":1,"text":"The issue log should be publicly available so all of your team members and stakeholders can view progress"},{"level":1,"text":"A simple issue tracking process makes it more likely that issues will appear in the log before they are forgotten"},{"level":2,"text":"Always ensure that users are adopting the processes"},{"level":1,"text":"A simple centralized list allows decision makers to compare the relative priority"},{"level":2,"text":"This also allows you to quickly generate reports and follow up on open issues"},{"level":1,"text":"Escalation Point"},{"level":2,"text":"Event that will activate a need to notify increasingly higher levels of authority"},{"level":1,"text":"An escalation path generally moves one or more levels up in the management hierarchy at each escalation point"},{"level":1,"text":"Dependencies are automatic escalation points"},{"level":1,"text":"Ensure issue reporting process is easy to use and accessible"},{"level":1,"text":"Establish effective communication channels"}]},{"id":"g131","part":13,"title":"Analyze the Issue","blocks":[{"level":1,"text":"An issue is just a visible manifestation of a deeper underlying problem"},{"level":1,"text":"Employing various quality tools can aid in detecting an issue and identifying its root cause"},{"level":1,"text":"Conducting a root cause analysis is crucial in determining why the issue is occurring"},{"level":1,"text":"Reviewing the issue log can help identify any other symptoms"},{"level":1,"text":"RCA enables better issue analysis and prioritization"},{"level":1,"text":"Resolving an issue may require several activities since you want to address both the symptoms and the root cause"},{"level":2,"text":"Scatter Diagram"},{"level":2,"text":"It involves plotting two variables, one on the x-axis and the other on the y-axis, and representing each occurrence of the (x,y) variable with a dot"},{"level":2,"text":"The diagram is useful in depicting the correlation between the variables"},{"level":2,"text":"It returns a mathematical value “R2” and the value ranges from -1 to 1"},{"level":2,"text":"Scatter diagrams are effective for large datasets and create an easy-to-read diagram"},{"level":2,"text":"Run Chart"},{"level":2,"text":"Line graph that displays data over time"},{"level":2,"text":"Pareto Charts"},{"level":2,"text":"The Pareto Principle suggests that fixing a small portion of root causes can solve most problems, with the 80/20 rule stating that 80% of issues stem from 20% of causes"},{"level":2,"text":"A Pareto chart can reveal that work was late for six reasons, with three of those reasons accounting for most of the delays"},{"level":2,"text":"Underestimating time requirements"},{"level":2,"text":"Needing to divert attention to operational work"},{"level":2,"text":"Experiencing hardware issues"},{"level":2,"text":"Five-Why Analysis"},{"level":2,"text":"Problem-solving technique that involves asking \"why\" questions to identify the root cause of a problem"},{"level":2,"text":"Fishbone Diagram"},{"level":2,"text":"The fish's head represents the problem, and the ribs represent possible related causes"},{"level":2,"text":"The fish's head represents the problem, and the ribs represent possible related causes, which can be categorized using the 6Ps (policy, process, people, plant, program, and product) or customized categories"}]},{"id":"g132","part":13,"title":"Issue Prioritization Tools","blocks":[{"level":1,"text":"Issue Analysis"},{"level":2,"text":"Used to determine the relative priority of an issue"},{"level":2,"text":"It is recommended to reevaluate the issue for two reasons"},{"level":2,"text":"The severity of the issue can be different from the risk assessment, especially with broad risks"},{"level":2,"text":"Evaluating issues against more detailed criteria can be useful since you have more information about them compared to unknown risks"},{"level":1,"text":"Several factors can be considered for analyzing issues, depending on the project and organization"},{"level":2,"text":"Severity"},{"level":2,"text":"Urgency"},{"level":2,"text":"Impact"},{"level":2,"text":"Scope of Impact"},{"level":2,"text":"Issue Escalation"},{"level":2,"text":"Issue Prioritization"},{"level":1,"text":"To measure the severity of an issue, estimate how it affects the average user"},{"level":1,"text":"Critical Issue"},{"level":2,"text":"Render the system completely inaccessible or nonfunctional"},{"level":1,"text":"Major Issue"},{"level":2,"text":"Allows the user to access the system, but one or more features are unavailable"},{"level":1,"text":"Minor Issue"},{"level":2,"text":"Do not affect the user experience, but they require a workaround"},{"level":1,"text":"Low-Severity Issue"},{"level":2,"text":"Do not affect functionality but should be resolved for branding, consistency, or improved user experience"},{"level":1,"text":"Urgency"},{"level":2,"text":"A metric that measures the time sensitivity of an issue and indicates how quickly it needs to be addressed"},{"level":1,"text":"Most companies use a simple scale with time limits for each level"},{"level":2,"text":"Critical Urgency"},{"level":2,"text":"Requires immediate resolution"},{"level":2,"text":"Major Urgency"},{"level":2,"text":"Requires resolution within hours"},{"level":2,"text":"Medium Urgency"},{"level":2,"text":"Requires resolution within days"},{"level":2,"text":"Minor Urgency"},{"level":2,"text":"Resolved at the earliest convenience"},{"level":1,"text":"The measure of impact quantifies the degree of influence an issue will have"},{"level":1,"text":"Examine how the issue will impact the project's scope, schedule, or budget"},{"level":1,"text":"A simple scale is used to measure the impact on a project"},{"level":2,"text":"High"},{"level":2,"text":"A project completion is at risk"},{"level":2,"text":"Medium"},{"level":2,"text":"A project delay is possible"},{"level":2,"text":"Low"},{"level":2,"text":"A project won’t be affected"},{"level":1,"text":"Assessing an issue's likelihood of escalation is a useful practice"},{"level":2,"text":"Issue Escalation"},{"level":2,"text":"Ensures critical risks and issues receive appropriate follow-up"},{"level":2,"text":"Escalated issues should be given a higher priority"},{"level":1,"text":"The issue escalation prioritization metric can also be measured using a simple scale, as follows"},{"level":2,"text":"High"},{"level":2,"text":"Has an escalation plan in place and has already been escalated"},{"level":2,"text":"Medium"},{"level":2,"text":"Has an escalation plan that has not been activated"},{"level":2,"text":"Low"},{"level":2,"text":"Do not have an issue escalation plan in place"},{"level":1,"text":"Issue Prioritization"},{"level":2,"text":"Involves a descriptive scale with paired numerical values that represent the actual score for each factor"},{"level":2,"text":"Typically, scores are arranged on a 1-9 scale, with 9 being the highest priority"},{"level":2,"text":"1-3-9 scale is ideal for scoring three options, such as low, medium, and high"},{"level":2,"text":"1-2-3 scale would result in most items having a relatively medium priority"},{"level":2,"text":"The same effect can be achieved with four values by using a 1-3-7- 9 scale"},{"level":2,"text":"This scale forces decisions by pushing high-priority items to the top"},{"level":1,"text":"To prioritize issues, you should identify relevant factors and add them as new columns in your issue log"},{"level":1,"text":"Calculate the relative issue prioritization score by summing the scores of each factor"}]},{"id":"g133","part":13,"title":"Resolve and Monitor the Issue","blocks":[{"level":1,"text":"Review the escalation plan to determine if an issue has been previously addressed"},{"level":1,"text":"Identify the owner of the issue and follow the escalation plan to notify the appropriate parties"},{"level":1,"text":"Issue owner is responsible for resolving the issue"},{"level":1,"text":"Lower-priority items may receive less attention than higher-priority items"},{"level":1,"text":"Contingency plans facilitate quick issue resolution by providing response plans"},{"level":1,"text":"Execute the contingency plan to safeguard assets and restore services"},{"level":1,"text":"Contingency plan enables the team to recover and resume work quickly"},{"level":1,"text":"The IT project managers need to conduct various monitoring activities to effectively implement the issue resolution plan, including"},{"level":2,"text":"Monitoring resolved issues"},{"level":2,"text":"Monitoring open issues"},{"level":2,"text":"Monitoring project performance"},{"level":1,"text":"PM is responsible for owning the issue log and following up with the listed owners"},{"level":1,"text":"It is also important to review assessment scores occasionally to ensure they still reflect reality"},{"level":1,"text":"To verify issue resolution, the project manager must verify and approve each completed resolution"},{"level":2,"text":"Check for any unintended consequences"},{"level":2,"text":"Confirm completion of all actions"},{"level":2,"text":"Ensure that the resolution addressed the problem"},{"level":1,"text":"Monitor which workarounds are implemented for each issue"},{"level":1,"text":"If the issue reoccurs, conduct another root cause analysis and work to resolve it"},{"level":1,"text":"By monitoring closed issues, you can identify trends and recurring problems, which can be used to make systemic improvements"},{"level":1,"text":"Include a summary of the issue in the lessons learned document"},{"level":2,"text":"This document should detail how the team approached the issue, what they learned, and what they would do differently next time"}]},{"id":"g134","part":13,"title":"Control Charts","blocks":[{"level":1,"text":"Control Charts"},{"level":2,"text":"Charts that use statistical methods to track the variation in a process over time"},{"level":1,"text":"When a process is performing as expected, it is said to be \"in control\""},{"level":1,"text":"If the process shows unacceptable levels of variation, it is considered \"out of control\""},{"level":1,"text":"The horizontal axis represents time or sequence, while the vertical axis represents the corresponding output"},{"level":1,"text":"A control chart distinguishes between statistically significant patterns in data and ordinary variation"},{"level":2,"text":"While run charts may appear to show trends, they can be misleading as common variation is present in every process"},{"level":1,"text":"Common Cause Variation"},{"level":2,"text":"The expected variation in a process and the control chart's limits are based on this"},{"level":1,"text":"Special Cause Variation"},{"level":2,"text":"Unique and changes something about the process, resulting in an unusual outcome"},{"level":1,"text":"Variation is a natural part of any process and does not necessarily indicate good or bad performance"},{"level":1,"text":"Use a control chart to verify that it is having the desired effect"},{"level":1,"text":"Identify areas where improvements can be made Control Change"}]},{"id":"g135","part":14,"title":"Control Change","blocks":[{"level":1,"text":"Change control helps identify which requests can be part of the project"},{"level":1,"text":"Change Control"},{"level":2,"text":"Systematic process of evaluating, approving, and managing proposed changes to project scope, objectives, deliverables, or other key aspects"},{"level":2,"text":"Ensuring that changes are properly assessed, documented, authorized, and implemented while minimizing disruption and maintaining project alignment"},{"level":1,"text":"Scope Change"},{"level":2,"text":"Modification, addition, or removal of project deliverables, objectives, requirements, or boundaries"},{"level":1,"text":"Scope Creep"},{"level":2,"text":"Gradual and uncontrolled expansion of project scope beyond its originally defined boundaries"},{"level":1,"text":"Different IT Change Delivery Methods"},{"level":2,"text":"Maintenance Windows"},{"level":2,"text":"Releases"},{"level":2,"text":"Customer Notifications"}]},{"id":"g136","part":14,"title":"Change Control Overview","blocks":[{"level":1,"text":"Change control process involves the submission of change requests, which are evaluated and either approved or denied"},{"level":1,"text":"The specific steps involved in the change control process may differ depending on the organization, but generally include four phases"},{"level":2,"text":"Initiating the request"},{"level":2,"text":"Evaluating the impacts"},{"level":2,"text":"Making a decision on the outcome"},{"level":2,"text":"Implementing the change"},{"level":1,"text":"Implementing a change control process ensures that a project remains aligned with business needs"},{"level":1,"text":"Change control improves traceability for project requirements"},{"level":1,"text":"Change control simplifies work and eliminate confusion"},{"level":1,"text":"Not every change requires a formal change control process"},{"level":1,"text":"The purpose of change control is to manage changes to the project's scope, time, and cost baselines"},{"level":1,"text":"Numerous events can trigger change requests during a project's execution phase as well"},{"level":2,"text":"Inconsistencies"},{"level":2,"text":"Aggressive goals"},{"level":2,"text":"Team improvements"},{"level":2,"text":"Strategic changes"},{"level":2,"text":"Scope changes"},{"level":2,"text":"Product changes"},{"level":1,"text":"A project is an activity that should be managed"},{"level":2,"text":"Project"},{"level":2,"text":"Creates or modifies products"},{"level":2,"text":"Product"},{"level":2,"text":"Outcome or component of value"},{"level":1,"text":"A product change may or may not cause a change in your project"},{"level":1,"text":"Change control can help to manage modifications to a project, product, or system"},{"level":2,"text":"It ensures that changes are:"},{"level":2,"text":"Aligned with business needs"},{"level":2,"text":"Enable stakeholders to review and approve changes"},{"level":2,"text":"Improve traceability for project requirements"},{"level":1,"text":"Difference between a project and product change"},{"level":2,"text":"Project Change"},{"level":2,"text":"Always impact the project"},{"level":2,"text":"Product Change"},{"level":2,"text":"May or may not require a project change"},{"level":1,"text":"Change control process helps manage changes in a more deliberate and informed manner"}]},{"id":"g137","part":14,"title":"Scope Change vs Scope Creep","blocks":[{"level":1,"text":"Scope Creep"},{"level":2,"text":"Refers to an unsanctioned alteration that generally increases work and extends the project, which is undesirable because it starts using additional resources, either time, money, or people"},{"level":1,"text":"Scope Change"},{"level":2,"text":"Sanctioned project adjustment that moves through approved channels"},{"level":2,"text":"A scope change also necessitates renegotiating scope, time, and budget, and altering any or all three baselines is an option"},{"level":1,"text":"To avoid scope creep, make scope change a possibility"},{"level":1,"text":"Focusing on the most crucial tasks helps deliver a high-quality product"},{"level":1,"text":"When we implement our changes, we have steps that must be followed"},{"level":2,"text":"Initiate the request"},{"level":2,"text":"Evaluate the impacts"},{"level":2,"text":"Decide on an outcome"},{"level":2,"text":"Implement the change"},{"level":1,"text":"Implementing a cloud solution involves using two important documents"},{"level":2,"text":"Change Request Form"},{"level":2,"text":"Used to gather information about a single change request"},{"level":2,"text":"It includes several fields that are commonly used in IT projects"},{"level":2,"text":"Project Name"},{"level":2,"text":"Date Requested"},{"level":2,"text":"Description"},{"level":2,"text":"Reason for Change"},{"level":2,"text":"Priority"},{"level":2,"text":"Impact"},{"level":2,"text":"Requested By"},{"level":2,"text":"Owner"},{"level":2,"text":"Deadline(s)"},{"level":2,"text":"Comments"},{"level":2,"text":"Change Log"},{"level":2,"text":"Contains all change requests for the project and is also known as a \"Change Control Log\""},{"level":2,"text":"The project manager enters the change request into the change log, adding relevant details such as an ID"},{"level":1,"text":"Implementing a cloud solution involves using two important documents"},{"level":1,"text":"The PM analyzes the request to determine how it will affect the project's resources, budget, scope, and schedule"},{"level":1,"text":"Hardware and software requests often necessitate a change in the product's requirements"},{"level":1,"text":"The PM compiles all the information about the change request"},{"level":2,"text":"Schedule Changes"},{"level":2,"text":"Scope Changes"},{"level":2,"text":"Risks"},{"level":2,"text":"Resource Requirements"},{"level":2,"text":"Notable Impacts"},{"level":1,"text":"After completing the impact analysis and developing a recommendation, PM presents these findings to the appropriate decision makers responsible for approving or denying the change"},{"level":1,"text":"Operational changes typically relate to the day-to-day business of running a project and have minimal impact on a project's cost, scope, or baseline"},{"level":1,"text":"CCB's authority establishes the PM's degree of authority over operational decision-making"},{"level":1,"text":"Strategic changes have effects beyond the boundaries of a project and impact the company's finances, book of business, or long-term goals"},{"level":1,"text":"The project sponsor, CCB, and PMO are the strategic decision makers for a project, with executive management delegating decision-making authority to these groups"},{"level":1,"text":"Changes related to a risk require the involvement of the risk owner as a decision maker"},{"level":1,"text":"As a project manager working on a project with a Change Control Board (CCB), responsibilities may be reduced"},{"level":2,"text":"PM will still receive change requests, maintain logs, conduct analyses, and make recommendations, the CCB formally takes ownership of project changes"},{"level":1,"text":"The following are some common types of software change approvals"},{"level":2,"text":"Technical Approval"},{"level":2,"text":"Involves review and input from subject matter experts who are familiar with the system"},{"level":2,"text":"This peer-review process can take various forms"},{"level":2,"text":"Technical Review"},{"level":2,"text":"Code Review"},{"level":2,"text":"Pair Programming"},{"level":2,"text":"Product Owner Approval"},{"level":2,"text":"Involves review and approve changes to confirm that the product meets all requirements"},{"level":2,"text":"Architectural Approval"},{"level":2,"text":"Ensures that the product positively affects the system"},{"level":1,"text":"Identify requests that are not technically feasible early on and flag them for review"},{"level":1,"text":"Once the change request outcome has been decided, the project manager (PM) will communicate the status of the change to relevant parties"},{"level":1,"text":"Consistent communication of project changes creates a shared understanding among stakeholders of the project's scope and schedule, builds strong relationships, and manages expectations"},{"level":1,"text":"The PM updates the project plan, depending on the nature of the change, by updating the following"},{"level":2,"text":"Schedule"},{"level":2,"text":"Deliverables"},{"level":2,"text":"Budget"},{"level":2,"text":"RACI Matrix"},{"level":2,"text":"Business Case"},{"level":2,"text":"Stakeholder Management Plan"},{"level":1,"text":"After validation, the PM notifies stakeholders of the completed change, including updates in recurring meetings and reports, such as the project status report"}]},{"id":"g138","part":14,"title":"IT Change Delivery Methods","blocks":[{"level":1,"text":"Different IT Change Delivery Methods"},{"level":2,"text":"Maintenance Windows"},{"level":2,"text":"Are blocks of time when IT systems are taken offline for maintenance or new releases"},{"level":2,"text":"By creating a timebox where multiple teams can perform functions on a system during the maintenance window, intentional changes can be consolidated, reducing downtime"},{"level":2,"text":"IT systems play a critical role in the operations of an organization"},{"level":2,"text":"Access to vital information such as customer data, payroll, website, orders, and product specifications is reliant on technology"},{"level":2,"text":"Releases"},{"level":2,"text":"Comprises a product's source code, including a collection of software improvements and modifications"},{"level":2,"text":"Customer Notifications"},{"level":2,"text":"Customers must be informed of any maintenance windows since they may experience disruptions and outages"},{"level":2,"text":"The IT technical team has many methods of notifying customers of maintenance windows"},{"level":2,"text":"Banner or Notice"},{"level":2,"text":"Message or Push Notification"},{"level":2,"text":"Email"},{"level":2,"text":"Text"},{"level":2,"text":"Social Media"},{"level":2,"text":"It's important to note that not every IT and software change warrants customer notification"},{"level":1,"text":"The IT Infrastructure Library (ITIL) categorizes changes into three types"},{"level":2,"text":"Standard Change"},{"level":2,"text":"Recurring changes with established policies and procedures that don’t require additional approval"},{"level":2,"text":"Normal Change"},{"level":2,"text":"Modifications that don’t have a set process and don’t occur frequently, but they’re also not emergency change"},{"level":2,"text":"Emergency Change"},{"level":2,"text":"Unplanned, recovery events that usually don’t allow time for advance notice"},{"level":1,"text":"Infrastructure changes are communicated through the same channels as software changes"},{"level":1,"text":"In general, customers should be notified if changes impact their user experience, access, account settings, or relationship with the company"},{"level":2,"text":"Example include changes to the following"},{"level":2,"text":"User Login Process"},{"level":2,"text":"Password Requirements"},{"level":2,"text":"Contracts"},{"level":2,"text":"Subscription Prices"},{"level":2,"text":"User Navigation"},{"level":1,"text":"Customers don't need to be notified of changes to internal workflows or data storage if it's undetectable by customers and not required by regulation"}]},{"id":"g139","part":14,"title":"IT Change Risk Mitigation","blocks":[{"level":1,"text":"2 Primary Forms of Backup Plans"},{"level":2,"text":"Rollback Plan"},{"level":2,"text":"It ensures that the team is prepared to restore the previous version of a system in case of a failed release"},{"level":2,"text":"It is a contingency plan that should be developed in advance"},{"level":2,"text":"A rollback plan serves as a last-resort option"},{"level":2,"text":"Post-Production Validation"},{"level":2,"text":"Are necessary to confirm that the software in production is performing as intended"},{"level":2,"text":"The QA team tests all changes in a test environment that match the production environment exactly"},{"level":2,"text":"The deployment procedures must flow in a specific sequence"},{"level":2,"text":"During the validation process, the QA engineer follows the same path as they did to test the software initially"},{"level":2,"text":"Complete the tests and record the results"},{"level":2,"text":"Report the results and identify issues and defects"}]},{"id":"g140","part":14,"title":"IT Environments","blocks":[{"level":1,"text":"On-premises change control is a more manual process compared to cloud changes"},{"level":1,"text":"Cloud deployments utilize automation to increase efficiency, leading to more frequent releases"},{"level":1,"text":"In an on-premises solution, the operations staff manually creates and manages data backups to support the rollback plan"},{"level":1,"text":"Cloud models integrate configuration and security checks"},{"level":1,"text":"Cloud computing adopts a shared responsibility model for security"},{"level":1,"text":"The organization is accountable for their internal policies, data security, and system configurations"},{"level":1,"text":"In contrast, on-premises infrastructure puts the organization in control of all security aspects, resulting in more significant responsibility"},{"level":1,"text":"As a note, organizations can improve on-premises deployments with process automation and supplemental integrations"},{"level":1,"text":"The software development environment is where software is developed, tested, and deployed"},{"level":2,"text":"The environment can also be referred to as a \"stage\" or \"tier”"},{"level":1,"text":"Organizations can create as many stages as they need to cover the entire DevOps cycle, but typically, three basic tier types are used"},{"level":2,"text":"Development Tier is where software is created, and it's available only to a single user locally"},{"level":2,"text":"Beta Tier is a test environment where developers push code from their development environment to test the changes made"},{"level":2,"text":"Production Tier is the live environment that end-users can access"},{"level":1,"text":"Cloud models also provide built-in features"},{"level":2,"text":"Data Backup"},{"level":2,"text":"Version Control"},{"level":2,"text":"Roll Back"},{"level":2,"text":"Security Checks Managing Performance"}]},{"id":"g141","part":15,"title":"Managing Performance","blocks":[{"level":1,"text":"Project's cost and schedule are not fixed"},{"level":1,"text":"Scope Burndown Chart"},{"level":2,"text":"Tracks the progress of a project's scope completion, helping the PM monitor the work and identify issues or delays"},{"level":1,"text":"Budget Burndown Chart"},{"level":2,"text":"Tracks the project's expenses against the budget"},{"level":1,"text":"Gap Analysis"},{"level":2,"text":"Used to identify variances between expected and actual results"},{"level":1,"text":"Contingency Reserve"},{"level":2,"text":"Process of using set-aside resources in a project to handle unforeseen risks or changes"},{"level":1,"text":"Earned Value Management (EVM)"},{"level":2,"text":"Monitoring method that uses planned value, earned value, and actual cost to track project performance"},{"level":1,"text":"The Estimate at Completion (EAC) and Estimate to Complete (ETC) are important metrics in earned value management"},{"level":2,"text":"4 Standard Methods for Calculating ETC"},{"level":2,"text":"Bottom-up"},{"level":2,"text":"Budgeted rate"},{"level":2,"text":"Cost Performance Index (CPI)"},{"level":2,"text":"Combination of CPI and Schedule Performance Index (SPI)"},{"level":1,"text":"The project schedule can be maintained at different levels of information"},{"level":2,"text":"Executive"},{"level":2,"text":"Milestone"},{"level":2,"text":"Detailed"}]},{"id":"g142","part":15,"title":"Scope and Budget Burndown Charts","blocks":[{"level":1,"text":"Scope Burndown Chart"},{"level":2,"text":"Graphical representation that tracks the progress of a project’s scope completion over time"},{"level":2,"text":"The chart displays the remaining work (in terms of scope items) that needs to be completed on the vertical axis and the time on the horizontal axis"},{"level":2,"text":"Burndown chart can be used to identify if the team is ahead or behind schedule"},{"level":1,"text":"Budget Burndown Chart"},{"level":2,"text":"Variation of the burndown chart that tracks the progress of a project's expenses over time"},{"level":2,"text":"Budget burndown compares the pace of expenses to the pace of the project"},{"level":1,"text":"Key difference between the budget burndown and other types of burndown charts"},{"level":2,"text":"Task Hours Burndown"},{"level":2,"text":"Have fewer task hours remaining than initially anticipated because it indicates that the project is ahead of schedule"},{"level":2,"text":"Budget Burndown"},{"level":2,"text":"Remaining actual budget to be equal or higher than the target budget"},{"level":1,"text":"PM interacts with the budget burndown at least weekly to assess the project's burn rate"},{"level":2,"text":"PMs manage vendor performance, which can significantly affect costs, and they are involved in selecting vendors, authorizing or managing resource utilization, scope changes, and buffer utilization"},{"level":1,"text":"Scope Burndown Chart helps the PM to understand how the progress of completing tasks affects the project's scope"},{"level":1,"text":"Budget Burndown Chart enables the PM to understand how the project's expenses affects the project budget"}]},{"id":"g143","part":15,"title":"Project Performance Gap Analysis","blocks":[{"level":1,"text":"Conducting gap analysis can help identify why the gap exists, followed by root cause analysis to identify the true cause of the variance"},{"level":1,"text":"Gap analysis allows the freedom to adjust either parameter, such as improving performance or changing the target"},{"level":1,"text":"Overly generous estimates can make data less reliable, so re-estimating work can be done to create a more realistic plan"},{"level":1,"text":"A burndown chart can identify a gap, it does not reveal the reason for it"},{"level":1,"text":"It's crucial to note that resolving gaps may take time, and gradual improvement should be expected"},{"level":1,"text":"Gap analysis can be a useful technique in agile projects to identify discrepancies between current and desired states and guide the development of solutions"},{"level":1,"text":"By using gap analysis to identify and prioritize key issues, the team is able to focus their efforts on the most impactful improvements"}]},{"id":"g144","part":15,"title":"Contingency Reserve Utilization","blocks":[{"level":1,"text":"Contingency Reserve Utilization"},{"level":2,"text":"The process of using contingency reserves in a project to address unexpected risks or changes that may impact project scope, timeline, or budget"},{"level":1,"text":"In an IT project, contingency reserve utilization can be used in several ways"},{"level":2,"text":"Addressing unforeseen risks"},{"level":2,"text":"Managing changes"},{"level":2,"text":"Mitigating schedule delays"},{"level":1,"text":"To use contingency reserve effectively, the project manager must have a clear understanding of the project risks and uncertainties, and develop a plan for how to address them"},{"level":1,"text":"By proactively allocating resources and developing a plan to address potential issues, project managers can help ensure project success and deliver on project objectives"},{"level":1,"text":"Using contingency reserves does not change the project cost baseline"}]},{"id":"g145","part":15,"title":"Earned Value Management","blocks":[{"level":1,"text":"Earned Value Management (EVM)"},{"level":2,"text":"A monitoring method used to track project performance based on three key values that monitor schedule and cost performance"},{"level":2,"text":"The three values used in EVM are"},{"level":2,"text":"Planned Value (PV)"},{"level":2,"text":"Represents the target cost and schedule"},{"level":2,"text":"Earned Value (EV)"},{"level":2,"text":"Represents the actual schedule"},{"level":2,"text":"Actual Cost (AC)"},{"level":2,"text":"Represents the actual cost"},{"level":1,"text":"Budget at Completion (BAC)"},{"level":2,"text":"Equals the project’s cost baseline"},{"level":1,"text":"The basic Earned Value Management (EVM) metrics can be calculated as follows"},{"level":2,"text":"Planned Value (PV)"},{"level":2,"text":"Represents the authorized budget assigned to the scheduled work"},{"level":2,"text":"PV = (planned percentage of work schedule) x (total budgeted cost of the work)"},{"level":2,"text":"Earned Value (EV)"},{"level":2,"text":"Represents the budgeted cost of the actual work performed"},{"level":2,"text":"EV = (actual percentage of work completed) X (total budgeted cost of the work)"},{"level":2,"text":"Actual Cost (AC)"},{"level":2,"text":"Represents the actual cost incurred in performing the work"},{"level":1,"text":"EVM metrics such as schedule variance (SV), cost variance (CV), schedule performance index (SPI), and cost performance index (CPI) can be computed"}]},{"id":"g146","part":15,"title":"Cost and Schedule Performance Metrics","blocks":[{"level":1,"text":"Earned Value Management (EVM)"},{"level":2,"text":"A monitoring method used to track project performance, based on three key values that monitor schedule and cost performance"},{"level":2,"text":"The three values used in EVM"},{"level":2,"text":"Planned Value (PV)"},{"level":2,"text":"Represents the target cost and schedule"},{"level":2,"text":"Earned Value (EV)"},{"level":2,"text":"Represents the actual schedule"},{"level":2,"text":"Actual Cost (AC)"},{"level":2,"text":"Represents the actual cost"},{"level":1,"text":"Cost Variance (CV)"},{"level":2,"text":"Measures the difference between earned value and actual cost"},{"level":2,"text":"Cost Variance = Earned Value – Actual Cost"},{"level":2,"text":"CV > 0"},{"level":2,"text":"Project is under budget"},{"level":2,"text":"CV = 0"},{"level":2,"text":"Project is spending exact amount"},{"level":2,"text":"CV < 0"},{"level":2,"text":"Project is over budget"},{"level":1,"text":"Cost Performance Index (CPI)"},{"level":2,"text":"Compares earned value against actual cost"},{"level":2,"text":"Cost Performance Index = Expected Value / Actual Cost"},{"level":2,"text":"CPI > 1"},{"level":2,"text":"Project is under budget"},{"level":2,"text":"CPI = 1"},{"level":2,"text":"Project is spending exact amount"},{"level":2,"text":"CPI < 1"},{"level":2,"text":"Project is over budget"},{"level":1,"text":"Schedule Variance (SV)"},{"level":2,"text":"Measures the difference between earned value and planned value"},{"level":2,"text":"Positive schedule variance means that the project delivers work faster than expected"},{"level":2,"text":"Schedule Variance = Expected Value – Planned Value"},{"level":2,"text":"SV > 0"},{"level":2,"text":"Project is ahead of schedule"},{"level":2,"text":"SV = 0"},{"level":2,"text":"Project is on pace with the estimates"},{"level":2,"text":"SV < 0"},{"level":2,"text":"Project is behind schedule"},{"level":1,"text":"Schedule Performance Index (SPI)"},{"level":2,"text":"Compares expected value and planned value"},{"level":2,"text":"Schedule Performance Index = Expected Value / Planned Value"},{"level":2,"text":"SPI > 1"},{"level":2,"text":"Project is ahead of schedule"},{"level":2,"text":"SPI < 0"},{"level":2,"text":"Project is not delivering value as fast as expected"}]},{"id":"g147","part":15,"title":"Forecasting Performance","blocks":[{"level":1,"text":"Estimate at Completion (EAC)"},{"level":2,"text":"Projected measurement of the overall cost of the project, based on previous performance"},{"level":1,"text":"Estimate to Complete (ETC)"},{"level":2,"text":"Anticipated cost to finish the remaining project work"},{"level":1,"text":"Estimate at Completion (EAC) = Actual Cost (AC) + Estimate to Complete (ETC)"},{"level":1,"text":"4 Standard Methods for Calculating the Estimate to Complete (ETC)"},{"level":2,"text":"Bottom-up"},{"level":2,"text":"Involves breaking down the remaining work into smaller components and estimating the cost of each component individually"},{"level":2,"text":"EAC = AC + ETC"},{"level":2,"text":"Where ETC is the sum of all remaining activities"},{"level":2,"text":"Budgeted Rate"},{"level":2,"text":"Involves calculating the budgeted rate for the remaining work and multiplying it by the remaining work"},{"level":2,"text":"EAC = AC + (BAC – EV)"},{"level":2,"text":"Cost Performance Index (CPI)"},{"level":2,"text":"Involves using the cost performance index (CPI) to forecast the cost of completing the remaining work"},{"level":2,"text":"EAC = BAC / CPI"},{"level":2,"text":"Combination of CPI and SPI"},{"level":2,"text":"Used to forecast the cost of completing the remaining work, taking into account both cost and schedule performance"},{"level":2,"text":"EAC = AC + ( [BAC-EV] / [CPI * SPI] )"},{"level":1,"text":"Variance at Completion (VAC)"},{"level":2,"text":"Measures the total variance the project is expected to experience"},{"level":2,"text":"VAC = BAC – EAC"}]},{"id":"g148","part":15,"title":"Rebaseline and Revise the Baseline","blocks":[{"level":1,"text":"Original baselines may no longer be an accurate reflection of the project's reality"},{"level":1,"text":"When change requests are introduced to a project, the cost, scope, or budget may be affected"},{"level":1,"text":"An increase in scope leads to an increase in cost and schedule"},{"level":1,"text":"PM is responsible for maintaining an up-to-date project budget"},{"level":1,"text":"The process of updating the project budget is similar to its creation, utilizing the same tools and processes"},{"level":1,"text":"What are some common reasons for updating the budget and timeline?"},{"level":2,"text":"When a new change request is received, the project team must assess its potential impact on the budget"},{"level":2,"text":"This analysis should consider resource allocation changes and changes to the number of project activities"},{"level":1,"text":"Approval of change requests can alter the project end date if the change affects the critical path"},{"level":1,"text":"Defect resolution activities must be included in the project schedule and budget"},{"level":1,"text":"As the project progresses, the team may gain insight into the required effort and activities needed, leading to improved estimation"},{"level":2,"text":"Improved estimation can positively or negatively impact the project's situation"},{"level":1,"text":"Rebaselining can be a recurring activity"},{"level":1,"text":"What types of project schedules are expected when we talk about adjusting timeline?"},{"level":2,"text":"Executive Schedule"},{"level":2,"text":"Outlines the project’s progress and outcomes, but it doesn’t include detailed activities"},{"level":2,"text":"Executive schedule changes only when there is a change in milestone or summary activity"},{"level":2,"text":"Milestone Schedule"},{"level":2,"text":"Used to monitor the project’s progress towards deliverables"},{"level":2,"text":"Milestone schedule changes when there is a change in the milestones or when activity changes result in new milestones"},{"level":2,"text":"Detailed Schedule"},{"level":2,"text":"Outlines project activity, duration, dependency, and milestone"},{"level":2,"text":"Changes to the project schedule require a change in the detailed schedule"},{"level":1,"text":"An updated milestone schedule should be prepared every time a change request is made"},{"level":1,"text":"Regularly updating the project management plan, including the project schedules, is good practice, and the project manager should maintain the schedule at least weekly"},{"level":2,"text":"The following are some of the schedule maintenance tasks that should be performed regularly"},{"level":2,"text":"Review the critical path"},{"level":2,"text":"Review resource utilization"},{"level":2,"text":"Review the current sprint plan"},{"level":2,"text":"Update the project schedule"},{"level":2,"text":"Publish updated project schedules"},{"level":2,"text":"Review project dashboards"},{"level":2,"text":"Prepare project status reports"}]},{"id":"g149","part":15,"title":"Project Dashboards","blocks":[{"level":1,"text":"Business Dashboard"},{"level":2,"text":"Provides a visual summary of comprehensive data from multiple sources"},{"level":2,"text":"Create dashboards for any summarize data, including projects, products, programs, departments, or teams"},{"level":1,"text":"KPIs measure how likely a project is to meet its goals, and if performing well, you can assume that the project is doing well"},{"level":2,"text":"A project should have 4-10 KPIs, consisting of a mix of outcome-focused and performance goals"},{"level":2,"text":"Number of users"},{"level":2,"text":"Generated revenue"},{"level":2,"text":"Performance to budget"},{"level":2,"text":"Cost per requirement"},{"level":2,"text":"Cost Variance (CV)"},{"level":2,"text":"Schedule Variance (SV)"},{"level":1,"text":"Some key differences between dashboards and reports"},{"level":2,"text":"Dashboards"},{"level":2,"text":"Updates continuously"},{"level":2,"text":"Interactive"},{"level":2,"text":"Reports"},{"level":2,"text":"Updated periodically"},{"level":2,"text":"Static"},{"level":2,"text":"Includes a snapshot of a dashboard but also provide additional information"},{"level":1,"text":"Executive Dashboard"},{"level":2,"text":"Designed for top-level management and provide a high-level overview of the organization's performance"},{"level":2,"text":"Audience"},{"level":2,"text":"Executive dashboards are designed for top-level management and provide a high-level overview of the organization's performance"},{"level":2,"text":"Content"},{"level":2,"text":"Executive dashboards typically display KPIs and metrics that are important to the organization's strategic goals"},{"level":2,"text":"Visualization"},{"level":2,"text":"Executive dashboards often use charts and graphs to present data in a visually appealing way"},{"level":2,"text":"Interactivity"},{"level":2,"text":"Executive dashboards may not be interactive, as they are designed to provide a high-level overview of the organization's performance"},{"level":1,"text":"Team Dashboard"},{"level":2,"text":"Designed for specific teams or departments and focus on team-specific metrics"},{"level":2,"text":"Audience"},{"level":2,"text":"Team dashboards are designed for specific teams or departments and focus on team-specific metrics"},{"level":2,"text":"Content"},{"level":2,"text":"Team dashboards focus on metrics that are relevant to the team's objectives, such as customer satisfaction or team productivity"},{"level":2,"text":"Visualization"},{"level":2,"text":"Team dashboards may use more detailed visuals, such as heat maps or sparklines, to display trends or patterns"},{"level":2,"text":"Interactivity"},{"level":2,"text":"Team dashboards may be more interactive, allowing team members to drill down into specific metrics or data points"},{"level":1,"text":"Project Manager Dashboard"},{"level":2,"text":"Designed for project managers and provide project-specific data"},{"level":2,"text":"Audience"},{"level":2,"text":"Project manager dashboards are designed for project managers and provide project-specific data"},{"level":2,"text":"Content"},{"level":2,"text":"Project manager dashboards show project-specific data, such as project status, task completion, and resource utilization"},{"level":2,"text":"Visualization"},{"level":2,"text":"Project manager dashboards may use Gantt charts or timelines to display project progress"},{"level":2,"text":"Interactivity"},{"level":2,"text":"Project manager dashboards are typically the most interactive, allowing project managers to make adjustments to the project plan or allocate resources as needed"},{"level":1,"text":"Dashboards can take on many different appearances, but they typically include graphic tiles, lists, gauges, and information blocks"},{"level":2,"text":"Design Principles of a Dashboard"},{"level":2,"text":"Intuitiveness"},{"level":2,"text":"A dashboard should be designed in a way that even a person with minimal training can interpret the information"},{"level":2,"text":"Actionable"},{"level":2,"text":"It should contain valuable information that allows the owner to know what actions they need to take within 30 seconds of looking at it"},{"level":2,"text":"Relevance"},{"level":2,"text":"They should contain information that the audience needs to know to make good decisions"},{"level":2,"text":"Timely"},{"level":2,"text":"Information should refresh at least as often as it is needed"},{"level":1,"text":"Brevity: A dashboard should contain only the necessary information and should not overwhelm users with unnecessary metrics"},{"level":1,"text":"Accuracy: High-quality data that reflects reality should be used to make decisions"},{"level":1,"text":"Sustainability: An automated dashboard that updates as source data is updated is ideal for long-term use Wrapping Up the Project"}]},{"id":"g150","part":16,"title":"Wrapping Up the Project","blocks":[{"level":1,"text":"The team prepares final reports, holds final meetings, and sends out surveys for the project"},{"level":1,"text":"As the team approaches the end of the execution phase, it's essential to begin planning for the end of the project"},{"level":1,"text":"Project teams can use OCM to reduce the stress generated by change"},{"level":1,"text":"Organizational Change Management (OCM)"},{"level":2,"text":"Systematic approach to managing and implementing changes within an organization"},{"level":1,"text":"High adoption rates are crucial for the success of change initiatives"},{"level":1,"text":"Monitoring and reinforcing adoption through feedback collection and ongoing support are important"},{"level":1,"text":"To effectively connect with end users during OCM, effective communication is key"},{"level":2,"text":"This includes frequent and early communication using various channels and encouraging two-way communication through open office hours or surveys"},{"level":2,"text":"Demonstrations, small group sessions, and personalized interactions can help gather feedback and address concerns"},{"level":1,"text":"Project closeout reviews involve finalizing activities to formally close the project"},{"level":1,"text":"The project scope document should be reviewed to confirm if objectives and deliverables have been met"},{"level":1,"text":"Contracts are closed by reviewing terms and ensuring all deliverables and payments have been completed"},{"level":1,"text":"Budget reconciliation verifies that transactions match actual activities or payments and resolves any discrepancies"},{"level":1,"text":"The closing phase of a project is often overlooked but is crucial for maintaining relationships and protecting the company"},{"level":2,"text":"Common deliverables in the closing phase include"},{"level":2,"text":"Project Closure Report"},{"level":2,"text":"Lessons Learned Report"},{"level":2,"text":"Final Project Documentation"},{"level":2,"text":"Final Deliverables"},{"level":2,"text":"Contract Closure Documentation"},{"level":2,"text":"Budget Reconciliation"},{"level":2,"text":"Handover Documentation"},{"level":1,"text":"Proper project closeout procedures should not be neglected as they maximize benefits, avoid negative consequences, and provide documentation for future reference"},{"level":1,"text":"Project Evaluation"},{"level":2,"text":"A methodical and unbiased assessment of a project's performance to identify areas for improvement"},{"level":2,"text":"Types of evaluations include self-evaluation, external evaluation, pre- project evaluation, ongoing evaluations, and post-project evaluation"},{"level":1,"text":"When planning a post-project evaluation, important steps include"},{"level":2,"text":"Create an evaluation plan"},{"level":2,"text":"Prepare for the evaluation"},{"level":2,"text":"Gather and analyze data"},{"level":2,"text":"Develop a summary report"},{"level":2,"text":"Impact"},{"level":2,"text":"Strengths"},{"level":2,"text":"Areas of improvement"},{"level":2,"text":"Plan for the next steps"},{"level":1,"text":"Project Closure Meeting"},{"level":2,"text":"Marks the end of the project and serves as the last working session"},{"level":1,"text":"Project Closeout Report"},{"level":2,"text":"Summarizes the meeting's discussions and additional performance data"},{"level":1,"text":"Resource Management Activities"},{"level":2,"text":"Collect feedback, remove accesses, release resources, archive document, and celebrate the project's success"}]},{"id":"g151","part":16,"title":"Organizational Change Management","blocks":[{"level":1,"text":"Organizational Change Management (OCM)"},{"level":2,"text":"Systematic approach to developing change plans that help change leaders overcome resistance"},{"level":1,"text":"Resistance is a natural defense mechanism against any event that could create discomfort"},{"level":1,"text":"Change adoption is a crucial metric that measures how many people use a new offering"},{"level":1,"text":"OCM is a strategy that ensures projects have high adoption rates"},{"level":1,"text":"OCM Plan"},{"level":2,"text":"A strategic approach to aid users in adjusting to changes"},{"level":2,"text":"The team then devises a plan to simplify the change, minimize resistance, and provide support"},{"level":1,"text":"During OCM implementation, the project team provides various forms of support, which serve as tools for stakeholders"},{"level":2,"text":"OCM is a customized and humanized approach"},{"level":2,"text":"The list of tools below should be treated like a menu rather than a checklist"},{"level":2,"text":"Training"},{"level":2,"text":"The team should identify the training requirements for different users, such as tool usage, concept comprehension, and process administration"},{"level":2,"text":"New Knowledge Base"},{"level":2,"text":"A knowledge base (KB) is a modular and living system containing instructions, articles, self-service guides, and troubleshooting tips for a product"},{"level":2,"text":"Documentation"},{"level":2,"text":"Documentation includes artifacts that can aid users in adopting and maintaining the new system over time"},{"level":2,"text":"Processes"},{"level":2,"text":"Documented instructions that describe how to complete tasks"}]},{"id":"g152","part":16,"title":"Connecting with End Users","blocks":[{"level":1,"text":"Effective communication is a crucial element of organizational change management"},{"level":2,"text":"It is important to communicate early and frequently using various channels"},{"level":2,"text":"Email"},{"level":2,"text":"Personal Conversations"},{"level":2,"text":"Group Meetings"},{"level":2,"text":"Relevant Training Sessions"},{"level":1,"text":"By maintaining consistent communication, you can address concerns, identify opportunities for improvement, and support the teams as they adapt to the changes"},{"level":1,"text":"Organizational change management requires a concerted effort to promote user adoption through effective communication, documentation, and training"},{"level":1,"text":"Change adoption percentage, measured by the number of active users, can serve as a useful metric"}]},{"id":"g153","part":16,"title":"Prepare for Project Closeout Reviews","blocks":[{"level":1,"text":"Before the formal closure, some project closing activities can be initiated"},{"level":2,"text":"Transferring deliverables"},{"level":2,"text":"Validating them"},{"level":2,"text":"Closing contracts"},{"level":2,"text":"Reconciling the budget"},{"level":1,"text":"Ensure that stakeholders are informed of the transition effects"},{"level":2,"text":"New Points of Contact"},{"level":2,"text":"Service License Agreement (SLA)"},{"level":1,"text":"To begin the closing process, start by reviewing the project scope document"},{"level":2,"text":"If the project is complete, confirm that it has achieved its objectives and delivered all the required deliverables"},{"level":2,"text":"If the project is suspended or canceled, prepare a summary outlining which deliverables are complete and to what degree, and communicate this to the stakeholders"},{"level":1,"text":"It is essential to obtain documented approval from each identified stakeholder that the project has met all the deliverables"},{"level":1,"text":"To close contracts, it is important to ensure that all stakeholders have approved the project closure"},{"level":2,"text":"Review the contract terms and ensure that all deliverables and activities have been completed"},{"level":2,"text":"Verify that all purchase orders (POs) have been submitted and invoices have been paid"},{"level":2,"text":"Confirm with vendors that they are not expecting additional payment, such as outstanding invoices or open expense reports"},{"level":1,"text":"When reconciling the budget, separation of duties should be employed whenever possible"},{"level":2,"text":"A reviewer who did not initiate, approve, or record the expenses should be used if possible"},{"level":2,"text":"Reconciliation"},{"level":2,"text":"A verification process in which each transaction in the budget is confirmed to match an actual activity or payment"},{"level":2,"text":"Verify that resource costs are correct for project activities and confirm that all POs are counted against the project budget"},{"level":2,"text":"Discrepancies should be researched and resolved"}]},{"id":"g154","part":16,"title":"Closing Phase Overview","blocks":[{"level":1,"text":"PM plays a vital role as the driving force behind initiating all closing activities"},{"level":1,"text":"Although the closing phase may seem routine, it is important to follow through with all necessary tasks"},{"level":2,"text":"Finalize documents"},{"level":2,"text":"Tie up loose ends"},{"level":2,"text":"Officially end the project"},{"level":1,"text":"It's important to note that stakeholders are already reaping the benefits of the project, and team members have mentally moved on to their next project"},{"level":1,"text":"PM must recognize when a project is ready to close"},{"level":2,"text":"Project objectives have been met"},{"level":2,"text":"Project is cancelled"},{"level":2,"text":"Project is suspended"},{"level":1,"text":"The specific deliverables included in the closing phase of a project may vary depending on the nature of the project and the organization's processes"},{"level":1,"text":"Some common deliverables that are typically included in the closing phase of a project"},{"level":2,"text":"Project Closure Report"},{"level":2,"text":"Documents the final status of the project and provides an overview of its accomplishments and challenges"},{"level":2,"text":"It includes the following information"},{"level":2,"text":"Objectives"},{"level":2,"text":"Scope"},{"level":2,"text":"Budget"},{"level":2,"text":"Schedule"},{"level":2,"text":"Lessons Learned Report"},{"level":2,"text":"Outlines the successes and failures of the project"},{"level":2,"text":"Final Project Documentation"},{"level":2,"text":"Includes all project documentation"},{"level":2,"text":"Project Plans"},{"level":2,"text":"Schedules"},{"level":2,"text":"Status Reports"},{"level":2,"text":"Meeting Minutes"},{"level":2,"text":"Other Project-Related Information"},{"level":2,"text":"Final Deliverables"},{"level":2,"text":"Services that were produced as a result of the project"},{"level":2,"text":"Contract Closure Documentation"},{"level":2,"text":"This includes all necessary paperwork to formally close out contracts with vendors, contractors, or other third-party providers"},{"level":2,"text":"Budget Reconciliation"},{"level":2,"text":"This involves comparing the final project budget to the actual expenditures and ensuring that all expenses are accounted for"},{"level":2,"text":"Handover Documentation"},{"level":2,"text":"This includes all necessary information and instructions for the operations team or other stakeholders who will be taking over the project's ongoing support and maintenance"},{"level":1,"text":"Do not neglect proper closeout procedures of a project"}]},{"id":"g155","part":16,"title":"Project Evaluation Overview","blocks":[{"level":1,"text":"A project evaluation is a methodical and unbiased assessment of a project's performance"},{"level":1,"text":"Project evaluations improve the current project's performance and the overall project management system"},{"level":1,"text":"To ensure that lessons learned benefit future projects, data should be consistently gathered, documented, and shared"},{"level":1,"text":"Evaluations foster a more engaging project by soliciting feedback from stakeholders"},{"level":1,"text":"Participation in project evaluations requires reflection and critical thinking"},{"level":1,"text":"Few types of evaluations that a project manager can utilize"},{"level":2,"text":"Self-Evaluation"},{"level":2,"text":"An activity that involves self-reflection to identify areas for improvement"},{"level":2,"text":"External Evaluation"},{"level":2,"text":"An evaluation conducted by a third party to provide an objective assessment of a product, service, or project"},{"level":2,"text":"External evaluations provide a fresh perspective and identify blind spots or weaknesses that may have been missed internally"},{"level":2,"text":"Pre-Project Evaluation"},{"level":2,"text":"An assessment of a project idea to determine if it’s worth pursuing"},{"level":2,"text":"Pre-project evaluations avoid wasting resources on projects that are not feasible or viable"},{"level":2,"text":"Ongoing Evaluation"},{"level":2,"text":"Evaluations conducted throughout the life cycle of a project to assess progress and identify opportunities for improvement"},{"level":2,"text":"Post-Project Evaluation"},{"level":2,"text":"An evaluation conducted after the completion of a project to assess its results and impact"},{"level":2,"text":"Post-project evaluations are important to learn from successes and failures and improve future projects"},{"level":2,"text":"When we start to plan our post-project evaluation, there are some steps involved"},{"level":2,"text":"Develop an evaluation plan"},{"level":2,"text":"Define the areas of interest"},{"level":2,"text":"Prepare for the evaluation"},{"level":2,"text":"List all the data points and performance metrics"},{"level":2,"text":"Gather and analyze data"},{"level":2,"text":"Implement the evaluation plan and set a time limit for collecting data"},{"level":2,"text":"Develop a summary report"},{"level":2,"text":"Create a concise report that provides the project evaluation results"},{"level":2,"text":"Summary includes stakeholder feedback to evaluate the project and its actual impact"},{"level":2,"text":"Plan for next steps"},{"level":2,"text":"Share the report with the project team and stakeholders, identify areas for improvement, and assign ownership"}]},{"id":"g156","part":16,"title":"Project Closure Meeting","blocks":[{"level":1,"text":"Project Closure Meeting"},{"level":2,"text":"Marks the end of the project and serves as the last working session"},{"level":1,"text":"During the meeting, the team discusses the project which includes"},{"level":2,"text":"Accomplishments"},{"level":2,"text":"Failures"},{"level":2,"text":"Challenges"},{"level":1,"text":"It's important to take note of every idea discussed during the meeting to determine how to apply them in future projects"},{"level":1,"text":"The agenda for a project meeting typically includes several items that cover the different aspects of the project"},{"level":2,"text":"Project Overview"},{"level":2,"text":"Which lists the goals, objectives, and success criteria of the project"},{"level":2,"text":"Project Highlights"},{"level":2,"text":"Outlines the project team's significant accomplishments"},{"level":2,"text":"Project Challenges are also discussed, as they are an excellent learning opportunity for the project team and other teams that may face similar issues"},{"level":2,"text":"Transparency is beneficial for everyone, so this item identifies the project's challenges and how the team met them"},{"level":2,"text":"Process Issues"},{"level":2,"text":"Technical Issues"},{"level":2,"text":"Underperforming Metrics"},{"level":2,"text":"Lessons Learned Workshop"},{"level":2,"text":"Is the largest agenda item, requiring about half of the scheduled meeting time?"},{"level":2,"text":"An end-of-project lessons learned session is held in this meeting"},{"level":2,"text":"This project closure activity aims to identify ways to improve future projects and is also called a \"post- mortem,\" \"project retrospective,\" or \"project review”"},{"level":2,"text":"During the lessons learned session, the PM discusses the project's final performance metrics, including cost, budget, and schedule"},{"level":2,"text":"Additionally, the group discusses the stakeholder feedback, remaining project evaluation topics, and any other project reflections"}]},{"id":"g157","part":16,"title":"Project Closeout Report","blocks":[{"level":1,"text":"Once the closure meeting concludes, the project manager (PM) must generate a project closeout report that outlines the meeting's discussions and includes additional performance data"},{"level":1,"text":"Project Closeout Report"},{"level":2,"text":"A comprehensive summary of the entire project and serves as an official request for project sign-off"},{"level":1,"text":"A project closure report typically includes the following contents"},{"level":2,"text":"Project Overview"},{"level":2,"text":"A brief description of the project, including the goals, objectives, and scope"},{"level":2,"text":"Deliverables"},{"level":2,"text":"A list of all the deliverables that were completed during the project, along with any relevant details"},{"level":2,"text":"Success Criteria"},{"level":2,"text":"A summary of how the project met its success criteria, including any metrics or KPIs that were used to measure success"},{"level":2,"text":"Project Highlights"},{"level":2,"text":"A section that outlines the project team's significant accomplishments, including any process improvements or successful delivery methods"},{"level":2,"text":"Project Challenges"},{"level":2,"text":"A description of the project's challenges and how the team overcame them, along with any lessons learned"},{"level":2,"text":"Future Considerations"},{"level":2,"text":"Ideas for future enhancements or follow-up work, along with action items and due dates"},{"level":2,"text":"Lessons Learned"},{"level":2,"text":"A summary of the lessons learned throughout the project, including feedback from stakeholders and customers"},{"level":2,"text":"Project Evaluation"},{"level":2,"text":"A final evaluation of the project's performance, including cost, budget, and schedule"},{"level":2,"text":"Sign-off Request"},{"level":2,"text":"A request for the project stakeholders and sponsor to sign off on the report, which officially closes the project"}]},{"id":"g158","part":16,"title":"Finish Resource Management Activities","blocks":[{"level":1,"text":"Effective resource management enables project managers to plan, allocate, and optimize resources to ensure that they are used efficiently and effectively throughout the project lifecycle"},{"level":1,"text":"PMs can identify and address any potential resource constraints or bottlenecks"},{"level":1,"text":"Completing resource management activities enables project managers to monitor and control resource usage"},{"level":2,"text":"This helps to maximize productivity, reduce waste, and increase profitability"},{"level":1,"text":"To reiterate, finishing resource management activities is critical for project success"},{"level":2,"text":"It enables project managers to optimize the use of resources, minimize project risks, and ensure that the project is delivered on time, within budget, and to the required quality standards"},{"level":2,"text":"What should we do to make this happen?"},{"level":2,"text":"Collect feedback from stakeholders"},{"level":2,"text":"Removes accesses"},{"level":2,"text":"Release resources"},{"level":2,"text":"Archive documentation"},{"level":2,"text":"Celebrate"},{"level":1,"text":"In the closing phase, collect feedback from both team members and stakeholders"},{"level":2,"text":"A survey is an effective way to gather final feedback as stakeholders have recently provided more interactive feedback during the project closure meeting"},{"level":2,"text":"This feedback should focus more on objective ratings and final comments, and an anonymous survey can generate the most transparent feedback"},{"level":1,"text":"At the end of the project, it is important to remove unnecessary access to prevent security issues and control costs"},{"level":1,"text":"Access management is a vital function in most organizations, and these tasks can be delegated to responsible groups"},{"level":1,"text":"PM should also check the access levels of team members, stakeholders, and vendors and identify which resources they have access to and which ones they no longer require"},{"level":1,"text":"We need to release the resources and officially disband the project team"},{"level":2,"text":"Acknowledge the end of the project work to anyone working on the project, including team members, contractors, and suppliers"},{"level":1,"text":"The project files will move to the organization's archives, so it is a good idea to keep a copy of any materials that will be useful for future projects"},{"level":2,"text":"Keep a copy or running list of lessons learned and maintain copies of templates, reusable processes, and checklists"},{"level":1,"text":"Take the time to acknowledge the team's contributions and celebrate the project's success Conclusion"}]},{"id":"g159","part":16,"title":"Conclusion","blocks":[{"level":1,"text":"4 Domains of Project+"},{"level":2,"text":"Domain 1: Project Management Concepts"},{"level":2,"text":"It makes up 33% of the exam"},{"level":2,"text":"Domain 2: Project Life Cycle Phases"},{"level":2,"text":"It makes up 30% of the exam"},{"level":2,"text":"Domain 3: Tools and Documentation"},{"level":2,"text":"It makes up 19% of the exam"},{"level":2,"text":"Domain 4: IT Basics and Governance"},{"level":2,"text":"It makes up 18% of the exam"},{"level":1,"text":"How do you sign up and schedule your exam?"},{"level":2,"text":"Pearson VUE"},{"level":2,"text":"You can take it at any Pearson VUE testing center worldwide, at either a local testing center or online"},{"level":2,"text":"You can buy that exam voucher by going to Pearson Vue directly when you're scheduling your exam at pearsonvue.com, or going to the voucher store at lpi.org to buy it from their online store"},{"level":2,"text":"Pearson VUE and LPI have now created a capability for you to take your certification exam online from the comfort of your home or office, using the Pearson VUE OnVue testing system"},{"level":2,"text":"Dion Training"},{"level":2,"text":"If you'd like to pre-purchase your exam voucher before you schedule the exam, you can actually save 10% off the price by going to our website at diontraining.com/vouchers"},{"level":2,"text":"Currently, we carry vouchers for over 50 countries around the world, and we are adding countries all the time"},{"level":2,"text":"As a LPI Platinum Partner, we receive a special discounted rate on these exam vouchers and we pass those savings onto our students when they order their exam vouchers from us"},{"level":1,"text":"Top five tips for increasing your score on the exam"},{"level":2,"text":"Use a cheat sheet"},{"level":2,"text":"You're not allowed to actually carry anything into the exam with you, but if you're at a local testing center, they will give you a whiteboard or a dry erase sheet that's about the size of a normal piece of paper"},{"level":2,"text":"Once the clock starts on the exam, you can brain-dump anything you want onto that paper"},{"level":2,"text":"Use the sheet and spend the first 1-2 minutes writing down those important things you may forget later on"},{"level":2,"text":"Skip any questions that are giving you trouble"},{"level":2,"text":"If you find yourself struggling with a really hard question, just mark it for review and skip it"},{"level":2,"text":"Students who do this end up increasing their score by at least 5% to 10% over their peers who try to do the simulations at the beginning of their exam"},{"level":2,"text":"Take a guess"},{"level":2,"text":"If you're in doubt, I want you to take a guess from the possible answer choices"},{"level":2,"text":"There is no penalty for guessing incorrectly on the exam"},{"level":2,"text":"If you are in doubt of the right answer, try to eliminate as many choices as possible and guess between the remaining answer options"},{"level":2,"text":"Pick the best time for your exam"},{"level":2,"text":"Pick the time of day that works best for you"},{"level":2,"text":"Don’t try to squeeze the exam in after working a long day at the office"},{"level":2,"text":"Be confident"},{"level":2,"text":"You’ve got this!"},{"level":2,"text":"You should already know you're going to pass!"},{"level":2,"text":"You should have already studied all the information in this course, you've watched the videos, you've taken the quizzes, you've studied your downloadable study notes"},{"level":2,"text":"If you're not confident right now, then wait a few days to schedule your exam"},{"level":2,"text":"Take a bunch of practice exams and build up your confidence"},{"level":1,"text":"When you take a practice exam, your goal is not to memorize the answer key"},{"level":2,"text":"You need to understand why the right answer was right and the wrong answers are wrong"},{"level":1,"text":"Good luck, and we hope to see you again in a future course as you continue upwards in your project management, IT, or cybersecurity career and continue to climb the CompTIA certification ladder!"}]});
